{"file_path": "C:\Users\UserX\.zcode\workspace\default\scan_size.ps1", "content": "param([string]$Root = 'C:\', [int]$TopN = 40, [int]$Depth = 0)

function Get-DirSize {
    param([string]$Path)
    $sum = 0L
    try {
        $items = Get-ChildItem -LiteralPath $Path -Force -Recurse -File -ErrorAction SilentlyContinue
        foreach ($i in $items) { $sum += $i.Length }
    } catch {}
    return $sum
}

$dirs = Get-ChildItem -LiteralPath $Root -Force -Directory -ErrorAction SilentlyContinue
$results = foreach ($d in $dirs) {
    # skip reparse points / junctions to avoid double counting and loops
    $isLink = $false
    try { $isLink = ($d.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 } catch {}
    if ($isLink) {
        [PSCustomObject]@{ Path = $d.FullName; SizeGB = -1; Note = 'REPARSE/SKIP' }
        continue
    }
    $s = Get-DirSize $d.FullName
    [PSCustomObject]@{ Path = $d.FullName; SizeGB = [math]::Round($s / 1GB, 2); Note = '' }
}

$results | Sort-Object SizeGB -Descending | Select-Object -First $TopN | Format-Table -AutoSize
"}

