{"content": "param(
    [string[]]$Roots = @('C:\Users\UserX','C:\Temp','C:\001','C:\models','C:\nodejs_package','C:\ultralytics-main','C:\MC','C:\SW99','C:\videos','C:\alll'),
    [double]$MinMB = 20
)

$min = $MinMB * 1MB
$files = foreach ($r in $Roots) {
    if (Test-Path -LiteralPath $r) {
        Get-ChildItem -LiteralPath $r -Force -Recurse -File -ErrorAction SilentlyContinue |
            Where-Object { $_.Length -ge $min -and $_.FullName -notmatch '\\AppData\\Local\\Programs\\|\\AppData\\Roaming\\Microsoft\\|\\node_modules\\.*\\' }
    }
}
Write-Host ("Candidate files: " + $files.Count)

# group by size first (cheap), only hash size-collisions
$groups = $files | Group-Object Length | Where-Object { $_.Count -gt 1 }
Write-Host ("Size-collision groups: " + $groups.Count)

$dups = New-Object System.Collections.Generic.List[object]
foreach ($g in $groups) {
    $byHash = $g.Group | Group-Object -Property { (Get-FileHash -LiteralPath $_.FullName -Algorithm MD5 -ErrorAction SilentlyContinue).Hash }
    foreach ($h in $byHash) {
        if ($h.Count -gt 1 -and $h.Name) {
            $dupBytes = ($h.Count - 1) * $g.Group[0].Length
            $dups.Add([PSCustomObject]@{
                FileMB   = [math]::Round($g.Group[0].Length / 1MB, 1)
                Copies   = $h.Count
                WastedGB = [math]::Round($dupBytes / 1GB, 2)
                Paths    = ($h.Group | ForEach-Object { $_.FullName }) -join ' | '
            })
        }
    }
}

$dups | Sort-Object WastedGB -Descending | Export-Csv -NoTypeInformation -Encoding UTF8 'C:\Users\UserX\.zcode\workspace\default\duplicates.csv'
$dups | Sort-Object WastedGB -Descending | Select-Object -First 40 | Format-Table -AutoSize -Wrap
'Duplicate groups: ' + $dups.Count
'Wasted total: ' + [math]::Round(($dups | Measure-Object -Property WastedGB -Sum).Sum, 2) + ' GB'
", "file_path": "C:\Users\UserX\.zcode\workspace\default\scan_dups.ps1"}

