{"content": "$log = 'C:\Users\UserX\.zcode\workspace\default\cleanup_log.txt'
function W($m) { $m | Tee-Object -FilePath $log -Append }

function Size-Of($p) {
    if (-not (Test-Path -LiteralPath $p)) { return -1 }
    $s = (Get-ChildItem -LiteralPath $p -Force -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    if ($null -eq $s) { return 0 }
    return [double]$s
}

# full = delete the directory itself; contents = delete only its children
$targets = @(
    @{ P = 'C:\Temp';                                              Mode = 'full' }
    @{ P = 'C:\tmp';                                               Mode = 'full' }
    @{ P = 'C:\Windows\Temp';                                      Mode = 'contents' }
    @{ P = 'C:\Users\UserX\AppData\Local\Temp';                    Mode = 'contents' }
    @{ P = 'C:\scitranslatetemp';                                  Mode = 'contents' }
    @{ P = 'C:\Windows\SoftwareDistribution\Download';             Mode = 'contents' }
    @{ P = 'C:\Users\UserX\AppData\Local\uv\cache';                Mode = 'full' }
    @{ P = 'C:\Users\UserX\AppData\Local\pip\cache';               Mode = 'full' }
    @{ P = 'C:\nodejs_package\npm_cache';                          Mode = 'full' }
    @{ P = 'C:\Users\UserX\.conda\pkgs';                           Mode = 'contents' }
    @{ P = 'C:\Users\UserX\.nuget\packages';                       Mode = 'contents' }
    @{ P = 'C:\Users\UserX\AppData\Local\NuGet\v3-cache';          Mode = 'contents' }
    @{ P = 'C:\Users\UserX\AppData\Local\JetBrains\PyCharmCE2024.2\index'; Mode = 'full' }
    @{ P = 'C:\Users\UserX\.cache\opencode';                      Mode = 'contents' }
)

W ('===== Tier1 cleanup start ' + (Get-Date).ToString('s') + ' =====')
$grand = 0.0
foreach ($t in $targets) {
    $p = $t.P
    $before = Size-Of $p
    if ($before -lt 0) { W ('SKIP (missing)          ' + $p); continue }

    $fail = 0
    if ($t.Mode -eq 'full') {
        try { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop } catch { $fail = 1 }
    } else {
        $kids = Get-ChildItem -LiteralPath $p -Force -ErrorAction SilentlyContinue
        foreach ($k in $kids) {
            try { Remove-Item -LiteralPath $k.FullName -Recurse -Force -ErrorAction Stop } catch { $fail++ }
        }
    }

    $after = Size-Of $p
    if ($after -lt 0) { $after = 0 }
    $freed = ($before - $after) / 1GB
    $grand += $freed
    W ('{0,8:N2} GB freed  {1}{2}  left={3:N2}GB  {4}' -f $freed, $p, $(if ($fail -gt 0) { '  [locked:' + $fail + ']' } else { '' }), ($after / 1GB), '')
}

$free = (Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'").FreeSpace
W ('--- Tier1 reclaimed (sum): {0:N2} GB' -f $grand)
W ('--- Current free space: {0:N2} GB' -f ($free / 1GB))
W '===== Tier1 cleanup end ====='
", "file_path": "C:\Users\UserX\.zcode\workspace\default\cleanup_tier1.ps1"}

